cards.css:
button {
  background-color: blue;
  color: white;
  padding: 15px 30px;
  border: none;
  font-size: 16px;
  cursor: pointer;
}

button:hover {
  background-color: red;
  transform: scale(1.1);
}

/* Cukup tambahkan transition di posisi aslinya */
.halus {
  transition: all 0.5s;
}

